mapper.select:
SELECT IFNULL(SUM(s.begin_quantity * a.net_weight),0) surplus_net_weight, IFNULL(SUM(s.begin_quantity * a.gross_weight),0) surplus_gross_weight,
IFNULL(SUM(s.task_quantity * a.net_weight),0) task_net_weight, IFNULL(SUM(s.task_quantity * a.gross_weight),0) task_gross_weight,
IFNULL(SUM(s.complete_quantity * a.net_weight),0) complete_net_weight, IFNULL(SUM(s.complete_quantity * a.gross_weight),0) complete_gross_weight,
IFNULL(SUM((s.in_production_quantity - s.complete_quantity) * a.net_weight),0) in_production_net_weight, IFNULL(SUM((s.in_production_quantity - s.complete_quantity) * a.gross_weight),0) in_production_gross_weight from mes_building_product_production_summary s inner join tech_artifact a on a.id = s.product_id where s.bool_delete_enum = 0 and s.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}
and s.project_id = #{projectId}
and s.monomer_id = #{monomerId}
and s.month = #{dateTime}

SELECT IFNULL(SUM(s.begin_quantity * a.length),0) surplus_length, IFNULL(SUM(s.begin_quantity * a.length * a.width),0) surplus_area,
IFNULL(SUM(s.task_quantity * a.length),0) task_length, IFNULL(SUM(s.task_quantity * a.length * a.width),0) task_area,
IFNULL(SUM(s.complete_quantity * a.length),0) complete_length, IFNULL(SUM(s.complete_quantity * a.length * a.width),0) complete_area,
IFNULL(SUM((s.in_production_quantity - s.complete_quantity) * a.length),0) in_production_length, IFNULL(SUM((s.in_production_quantity - s.complete_quantity) * a.length * a.width),0) in_production_area from mes_building_product_production_summary s inner join tech_enclosure a on a.id = s.product_id where s.bool_delete_enum = 0 and s.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ENCLOSURE.getType()}
and s.project_id = #{projectId}
and s.monomer_id = #{monomerId}
and s.month = #{dateTime}

select p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', temp.* from ( select a.project_id, a.monomer_id, a.name, a.material, IFNULL(SUM(s.begin_quantity + s.task_quantity),0) task_quantity, IFNULL(SUM((s.begin_quantity + s.task_quantity) * a.net_weight),0) task_net_weight, IFNULL(SUM((s.begin_quantity + s.task_quantity) * a.gross_weight),0) task_gross_weight, IFNULL(SUM(s.complete_quantity),0) complete_quantity, IFNULL(SUM(s.complete_quantity * a.net_weight),0) complete_net_weight, IFNULL(SUM(s.complete_quantity * a.gross_weight),0) complete_gross_weight, IFNULL(SUM(s.in_production_quantity - s.complete_quantity),0) in_production_quantity, IFNULL(SUM((s.in_production_quantity - s.complete_quantity) * a.net_weight),0) in_production_net_weight, IFNULL(SUM((s.in_production_quantity - s.complete_quantity) * a.gross_weight),0) in_production_gross_weight from mes_building_product_production_summary s inner join tech_artifact a on a.id = s.product_id where s.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}
and s.project_id = #{projectId}
and s.monomer_id = #{monomerId}
and s.month = #{dateTime}
group by a.project_id,a.monomer_id,a.name,a.material) temp inner join contract_project p on p.id = temp.project_id inner join plan_monomer m on m.id = temp.monomer_id

select p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', temp.* from ( select a.project_id, a.monomer_id, a.name, a.material, IFNULL(SUM(s.begin_quantity + s.task_quantity),0) task_quantity, IFNULL(SUM((s.begin_quantity + s.task_quantity) * a.length),0) task_length, IFNULL(SUM((s.begin_quantity + s.task_quantity) * a.length * a.width),0) task_area, IFNULL(SUM(s.complete_quantity),0) complete_quantity, IFNULL(SUM(s.complete_quantity * a.length),0) complete_length, IFNULL(SUM(s.complete_quantity * a.length * a.width),0) complete_area, IFNULL(SUM(s.in_production_quantity - s.complete_quantity),0) in_production_quantity, IFNULL(SUM((s.in_production_quantity - s.complete_quantity) * a.length),0) in_production_length, IFNULL(SUM((s.in_production_quantity - s.complete_quantity) * a.length * a.width),0) in_production_area from mes_building_product_production_summary s inner join tech_enclosure a on a.id = s.product_id where s.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ENCLOSURE.getType()}
and s.project_id = #{projectId}
and s.monomer_id = #{monomerId}
and s.month = #{dateTime}
group by a.project_id,a.monomer_id,a.name,a.material) temp inner join contract_project p on p.id = temp.project_id inner join plan_monomer m on m.id = temp.monomer_id

select ta.id,ta.`name`,ta.material,ta.serial_number, a.task_quantity, a.complete_quantity, IFNULL(a.task_quantity * ta.net_weight,0) task_net_weight, IFNULL(a.task_quantity * ta.gross_weight,0) task_gross_weight, IFNULL(a.complete_quantity * ta.net_weight,0) complete_net_weight, IFNULL(a.complete_quantity * ta.gross_weight,0) complete_gross_weight, p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', d.`id` 'area.id', d.`name` 'area.name' from ( SELECT a.product_id, sum( IFNULL( a.task_quantity, 0 )) task_quantity, sum(IFNULL( b.complete_quantity, 0 )) complete_quantity FROM ( SELECT product_id, sum( task_quantity ) task_quantity FROM mes_building_task WHERE bool_delete_enum = 0 AND product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}
AND project_id in
#{projectId}
AND project_id=#{projectId}
AND monomer_id=#{monomerId}
AND DATE_FORMAT( create_time, '%Y-%m' )<= #{dateTime} GROUP BY product_id ) a LEFT JOIN ( SELECT product_id, sum( quantity ) complete_quantity FROM mes_building_complete WHERE bool_delete_enum = 0 AND product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()} AND DATE_FORMAT( create_time, '%Y-%m' )<= #{dateTime} GROUP BY product_id ) b ON a.product_id = b.product_id LEFT JOIN ( SELECT product_id, sum( quantity ) in_production_quantity FROM mes_building_in_production WHERE bool_delete_enum = 0 AND product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()} AND DATE_FORMAT( create_time, '%Y-%m' )<= #{dateTime} GROUP BY product_id ) c ON a.product_id = c.product_id WHERE IFNULL( complete_quantity, 0 )>0 GROUP BY product_id ) a inner JOIN tech_artifact ta ON ta.id=a.product_id AND ta.bool_delete_enum=0 inner JOIN contract_project p ON ta.project_id = p.id inner JOIN plan_monomer m ON ta.monomer_id = m.id inner JOIN plan_area d ON ta.area_id = d.id

select ta.id,ta.`name`,ta.material,ta.serial_number, a.task_quantity, a.complete_quantity, IFNULL(a.task_quantity * ta.length,0) task_length, IFNULL(a.task_quantity * ta.length*ta.width,0) task_area, IFNULL(a.complete_quantity * ta.length,0) complete_length, IFNULL(a.complete_quantity * ta.length*ta.width,0) complete_area, p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', d.`id` 'area.id', d.`name` 'area.name' from ( SELECT a.product_id, sum( IFNULL( a.task_quantity, 0 )) task_quantity, sum(IFNULL( b.complete_quantity, 0 )) complete_quantity FROM ( SELECT product_id, sum( task_quantity ) task_quantity FROM mes_building_task WHERE bool_delete_enum = 0 AND product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ENCLOSURE.getType()}
AND project_id in
#{projectId}
AND project_id=#{projectId}
AND monomer_id=#{monomerId}
AND DATE_FORMAT( create_time, '%Y-%m' )<= #{dateTime} GROUP BY product_id ) a LEFT JOIN ( SELECT product_id, sum( quantity ) complete_quantity FROM mes_building_complete WHERE bool_delete_enum = 0 AND product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ENCLOSURE.getType()} AND DATE_FORMAT( create_time, '%Y-%m' )<= #{dateTime} GROUP BY product_id ) b ON a.product_id = b.product_id LEFT JOIN ( SELECT product_id, sum( quantity ) in_production_quantity FROM mes_building_in_production WHERE bool_delete_enum = 0 AND product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ENCLOSURE.getType()} AND DATE_FORMAT( create_time, '%Y-%m' )<= #{dateTime} GROUP BY product_id ) c ON a.product_id = c.product_id WHERE IFNULL( complete_quantity, 0 )>0 GROUP BY product_id ) a inner JOIN tech_enclosure ta ON ta.id=a.product_id AND ta.bool_delete_enum = 0 inner JOIN contract_project p ON ta.project_id = p.id inner JOIN plan_monomer m ON ta.monomer_id = m.id inner JOIN plan_area d ON ta.area_id = d.id

select ta.id,ta.`name`,ta.material,ta.serial_number, a.task_quantity, a.in_production_quantity, IFNULL(a.task_quantity * ta.net_weight,0) task_net_weight, IFNULL(a.task_quantity * ta.gross_weight,0) task_gross_weight, IFNULL(a.in_production_quantity * ta.net_weight,0) in_production_net_weight, IFNULL(a.in_production_quantity * ta.gross_weight,0) in_production_gross_weight, p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', d.`id` 'area.id', d.`name` 'area.name' from ( SELECT a.product_id, sum( IFNULL( a.task_quantity, 0 )) task_quantity, sum( IFNULL( c.in_production_quantity, 0 )- IFNULL( b.complete_quantity, 0 )) in_production_quantity FROM ( SELECT product_id, sum( task_quantity ) task_quantity FROM mes_building_task WHERE bool_delete_enum = 0 AND product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}
AND project_id in
#{projectId}
AND project_id=#{projectId}
AND monomer_id=#{monomerId}
AND DATE_FORMAT( create_time, '%Y-%m' )<= #{dateTime} GROUP BY product_id ) a LEFT JOIN ( SELECT product_id, sum( quantity ) complete_quantity FROM mes_building_complete WHERE bool_delete_enum = 0 AND product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()} AND DATE_FORMAT( create_time, '%Y-%m' )<= #{dateTime} GROUP BY product_id ) b ON a.product_id = b.product_id LEFT JOIN ( SELECT product_id, sum( quantity ) in_production_quantity FROM mes_building_in_production WHERE bool_delete_enum = 0 AND product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()} AND DATE_FORMAT( create_time, '%Y-%m' )<= #{dateTime} GROUP BY product_id ) c ON a.product_id = c.product_id WHERE IFNULL( c.in_production_quantity, 0 )> IFNULL( complete_quantity, 0 ) GROUP BY product_id ) a inner JOIN tech_artifact ta ON ta.id=a.product_id AND ta.bool_delete_enum=0 inner JOIN contract_project p ON ta.project_id = p.id inner JOIN plan_monomer m ON ta.monomer_id = m.id inner JOIN plan_area d ON ta.area_id = d.id

