SELECT
IFNULL(SUM( quantity ),0) complete_quantity
FROM
mes_building_complete a
WHERE a.bool_delete_enum = FALSE
  AND a.product_id = #{productId}
  AND a.product_type = #{productType}
  AND DATE_FORMAT(a.create_time, '%Y-%m') <= #{dateTime}
